<template>
  <baseLayout :foot-style="{height:'130px'}" v-loading="loading">
    <div class="main-wrap">
      <div class="search-wrap">
        <div class="welcome" :class="{'welcome-en':$i18n.locale === 'en'}">
          <!-- 欢迎使用外贸狼智能营销版 -->
          {{ $t('layout.welcome') }}
        </div>
        <div class="search-btn-box">
          <div>
            <!-- 请输入您的精准核心产品关键字 -->
            <input
              ref="search-input"
              class="search-input"
              @keyup.enter="goCreateTask"
              v-model="keyword"
              :placeholder="$t('layout.keywordTip')"
              type="text"
            />
            <div class="entry-tip">
              <i class="el-icon-view"></i>
              <!-- 新手入门必看 -->
              {{ $t('layout.beginMustSee') }}
            </div>
          </div>
          <button class="select-file-btn" @click="goCreateTask">
            <!-- 创建营销任务 -->
            {{ $t('layout.createBtnText') }}
          </button>
        </div>
      </div>

      <div class="adsense-wrap"></div>

      <div class="tutorial-title">
        <div class="title-box">
          <!-- 软件教程 -->
          {{ $t('layout.softwareTutorial') }}
        </div>
      </div>

      <div class="tutorial-list">
        <div class="tutorial-item">
          <div class="tutorial-item-ad tutorial-item-ad1"></div>
        </div>
        <div class="tutorial-item">
          <div class="tutorial-item-ad tutorial-item-ad2"></div>
        </div>
        <div class="tutorial-item">
          <div class="tutorial-item-ad tutorial-item-ad3"></div>
        </div>
      </div>
    </div>
  </baseLayout>
</template>

<script>
export default {
  data: function () {
    return {
      fileUid: '',
      loading: false,
      taskValue: '',
      keyword: ''
    }
  },
  methods: {
    /**
     * @author: vince.Liang
     * @function: 请求产品关键字列表并跳转创建任务流程首页
     * @data: 2019-3-27
     * @param none
     * @return:undefined
     */
    async goCreateTask () {
      // 请输入您的精准核心产品关键字
      let errorMsg = this.$WmlValidator.validate(this.keyword, [{ rule: 'isNonNull', errorMsg: this.$t('layout.keywordTip') }])
      if (errorMsg) {
        this.$WmlMsg(errorMsg, 'warning')
        return
      }
      this.$refs['search-input'].blur()
      // 您的核心产品关键字为 "${this.keyword}" ,确定并立刻开始创建任务？
      let confirm = await this.$WmlConfirm(`${this.$t('layout.keywordConfirmBody0')} "${this.keyword}" ,${this.$t('layout.keywordConfirmBody1')}？`)
      if (!confirm) return
      this.loading = true
      this.SharpObj.getRecommendKW(this.keyword, async res => {
        try {
          res = JSON.parse(res)
          this.loading = false
          if (res.Code === 0) {
            this.$to({ path: '/task/index/', query: { keyword: this.keyword, keywordOption: res.Data } })
          } else if (res.Code === 2) {
            let confirm = await this.$WmlConfirm(res.Msg)
            if (!confirm) return
            this.$to({ path: '/task/index/', query: { keyword: this.keyword, keywordOption: res.Data } })
          } else {
            this.$WmlMsg(res.Msg, 'warning')
          }
        } catch (err) {
          this.loading = false
          this.$WmlMsg(this.$t('common.networkErrorTip'), 'warning')
        }
      })
    }

  }
}
</script>

<style scoped>
button {
  border: 0;
}

.main-wrap {
  width: 100%;
  height: 100%;
  overflow: auto;
}

.search-wrap {
  background-color: #fbfbfb;
  width: 100%;
  height: 460px;
  background-size: 100% 100%;
  border-top: 1px solid black;
  border-color: rgba(255, 123, 123, 0);
  background-image: url("../../assets/image/indexSearchBg.jpg");
  background-size: 100% 100%;
  display: flex;
  flex-wrap: wrap;
  align-content: center;
  align-items: center;
}

.welcome {
  width: 100%;
  font-size: 30px;
  line-height: 68px;
  color: #0090fe;
  letter-spacing: 6px;
  transform: translateY(-30px);
  text-align: center;
}

.welcome-en {
  letter-spacing: 0px;
  font-size: 30px;
  font-weight: 700;
}

.search-btn-box {
  width: 100%;
  display: flex;
  justify-content: center;
}

.search-input {
  height: 50px;
  line-height: 50px;
  color: #545454;
  padding: 0 10px;
  width: 480px;
  border: 1px solid #cfcfcf;
  box-shadow: 0 0 3px #ccc inset;
  border-top-left-radius: 3px;
  border-bottom-left-radius: 3px;
  border-right: 0;
}

.upload-btn,
.select-file-btn {
  height: 50px;
  line-height: 50px;
  padding: 0 10px;
  border-color: #cfcfcf;
  color: #fff;
  cursor: pointer;
  background-color: #0090fe;
  border-top-right-radius: 3px;
  border-bottom-right-radius: 3px;
}

.upload-btn {
  margin-left: 10px;
  background-color: #0f97ff;
}

.entry-tip {
  line-height: 38px;
  font-size: 13px;
  color: #0f97ff;
  text-decoration: underline;
  cursor: pointer;
  transform: translateX(8px);
  margin-top: 18px;
}

.entry-tip:hover {
  color: #0daeff;
}

.entry-tip > i {
  font-size: 17px;
  margin-right: 3px;
}

.adsense-wrap {
  width: 100%;
  height: 130px;
  background-image: url("../../assets/image/adsenseBg.png");
  background-size: cover;
  background-repeat: no-repeat;
  text-align: center;
  cursor: pointer;
  background-position: center;
}
.tutorial-title {
  display: flex;
  justify-content: space-between;
  margin: 10px 60px;
  border-bottom: 1px solid #f2f2f2;
  padding-bottom: 10px;
}

.title-box {
