}

.tutorial-list {
  padding: 0 60px;
  display: flex;
  justify-content: space-between;
  margin-top: 19px;
}

.tutorial-item {
  width: 32%;
}

.tutorial-item-ad {
  width: 100%;
  height: 173px;
  background-position: center;
  background-size: contain;
  background-repeat: no-repeat;
  cursor: pointer;
}

.tutorial-item-ad1 {
  background-image: url("../../assets/image/tutorial1.jpg");
}

.tutorial-item-ad2 {
  background-image: url("../../assets/image/tutorial2.jpg");
}

.tutorial-item-ad3 {
  background-image: url("../../assets/image/tutorial3.jpg");
}

.tutorial-item-ul {
  width: 100%;
}

.tutorial-item-li {
  height: 38px;
  line-height: 38px;
  color: #666;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  cursor: pointer;
}

.tutorial-item-li:hover {
  color: #00a9ff;
}

.tutorial-more {
  font-size: 13px;
  color: #666;
  margin-top: 10px;
}

